import {requestCapabilityReview} from '../src/services/capability-review.js';
import fs from 'node:fs';import {loadConfig} from '../src/config/index.js';import {ProviderAdapter} from '../src/providers/adapter.js';process.loadEnvFile();const config=loadConfig(),p=config.ai.providers.find(p=>p.id==='gemini'),out='docs/verification/gemini-routing-20261106';fs.mkdirSync(out,{recursive:true});const journal=out+'/live-attempt.json';if(fs.existsSync(journal))throw Error('The authorized attempt was already recorded; no second request permitted');if(p.model!=='gemini-3.8-flash'||!p.key)throw Error('Configured key/model differs; stop');const url=p.base+'/models/'+encodeURIComponent(p.model),r=await fetch(url,{headers:{'x-goog-api-key':p.key},signal:AbortSignal.timeout(15000),redirect:'error'});if(!r.ok){console.log(JSON.stringify({model:p.model,catalogHTTP:r.status,generationRequests:0}));process.exit(1);}const model=await r.json();if(model.name!=='models/'+p.model||!model.supportedGenerationMethods?.includes('generateContent'))throw Error('Exact model generation capability absent; no generation');fs.writeFileSync(out+'/model.json',JSON.stringify({name:model.name,methods:model.supportedGenerationMethods,input:model.inputTokenLimit,output:model.outputTokenLimit,checkedAt:new Date().toISOString()},null,2));const adapter=new ProviderAdapter(p,{timeout:60000,tokenLimit:500});adapter.verifyBeforeGenerate=async()=>{if(!p.free)throw Error('Persistent free confirmation is false; do not dispatch');};adapter.responseJsonSchema={type:'object',properties:{explanation:{type:'string'},edgeCase:{type:'string'},improvement:{type:'string'},code:{type:'string'},tests:{type:'array',items:{type:'string'},minItems:2,maxItems:2}},required:['explanation','edgeCase','improvement','code','tests'],additionalProperties:false};const prompt={system:'Return concise JSON only, matching the supplied schema. Explain code, identify a real invalid-input edge case, suggest a small improvement, return a corrected JavaScript calculateTotal function and exactly two meaningful test suggestions. Do not claim tests ran. Keep the answer short. Do not use tools or external services.',user:'Review this disposable example:\nfunction calculateTotal(prices) {\n  let total = 0;\n  for (let i = 0; i < prices.length; i++) { total += prices[i]; }\n  return total;\n}\nRequire an array of finite numbers and reject invalid inputs; return the corrected function in code, and two test suggestions.'};fs.writeFileSync(journal,JSON.stringify({approvedBy:'owner',confirmation:'Free access confirmed — approve one test',model:p.model,maxOutputTokens:500,timeoutMs:60000,noRetry:true,noFallback:true,attemptedAt:new Date().toISOString()},null,2),{flag:'wx'});const started=Date.now();try{const result=await requestCapabilityReview(adapter,prompt);const review=result.review;const valid=['explanation','edgeCase','improvement','code'].every(k=>typeof review[k]==='string'&&review[k].trim())&&review.tests?.length===2&&review.tests.every(t=>typeof t==='string'&&t.trim());const record={model:p.model,httpStatus:result.diagnostics?.httpStatus,elapsedMs:Date.now()-started,timeoutMs:60000,finishReason:result.finishReason,usage:result.usage,complete:true,structuredValid:valid,review,generationRequests:1,costUSD:null,costEvidence:'Owner-confirmed Free Tier; provider response is not a billing statement'};fs.writeFileSync(out+'/live-result.json',JSON.stringify(record,null,2));console.log(JSON.stringify({model:record.model,httpStatus:record.httpStatus,elapsedMs:record.elapsedMs,finishReason:record.finishReason,usage:record.usage,complete:true,structuredValid:valid},null,2));}catch(e){const record={model:p.model,httpStatus:e.httpStatus||adapter.lastDiagnostics?.httpStatus||null,elapsedMs:Date.now()-started,timeoutMs:60000,finishReason:e.finishReason||null,usage:e.usage||null,complete:false,code:e.code||'local_response_validation',error:e.code?'Sanitized provider failure: '+e.code:'Response did not match the expected JSON contract',partialFinalText:e.partialFinalText||null,generationRequests:1};fs.writeFileSync(out+'/live-result.json',JSON.stringify(record,null,2));console.log(JSON.stringify({...record,partialFinalText:undefined},null,2));process.exitCode=1;}
